g openchoreo","tree":{"sha":"146d16543e66ebed719489fb62908430d2356897","url":"https://api.github.com/repos/cuongct924/AI-delivery-portal-backend/git/trees/146d16543e66ebed719489fb62908430d2356897"},"url":"https://api.github.com/repos/cuongct924/AI-delivery-portal-backend/git/commits/9301b7caca23e7ee82484884f18f930937a97535","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/111407982?v=4","events_url":"https://api.github.com/users/cuongct924/events{/privacy}","followers_url":"https://api.github.com/users/cuongct924/followers","following_url":"https://api.github.com/users/cuongct924/following{/other_user}","gists_url":"https://api.github.com/users/cuongct924/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/cuongct924","id":111407982,"login":"cuongct924","node_id":"U_kgDOBqPzbg","organizations_url":"https://api.github.com/users/cuongct924/orgs","received_events_url":"https://api.github.com/users/cuongct924/received_events","repos_url":"https://api.github.com/users/cuongct924/repos","site_admin":false,"starred_url":"https://api.github.com/users/cuongct924/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/cuongct924/subscriptions","type":"User","url":"https://api.github.com/users/cuongct924","user_view_type":"public"},"html_url":"https://github.com/cuongct924/AI-delivery-portal-backend/commit/9301b7caca23e7ee82484884f18f930937a97535","node_id":"C_kwDOTV01PNoAKDkzMDFiN2NhY2EyM2U3ZWU4MjQ4NDg4NGYxOGY5MzA5MzdhOTc1MzU","parents":[{"html_url":"https://github.com/cuongct924/AI-delivery-portal-backend/commit/30f2e1f07aff8353c1b5d20e45e5c5ec3d03e8af","sha":"30f2e1f07aff8353c1b5d20e45e5c5ec3d03e8af","url":"https://api.github.com/repos/cuongct924/AI-delivery-portal-backend/commits/30f2e1f07aff8353c1b5d20e45e5c5ec3d03e8af"}],"sha":"9301b7caca23e7ee82484884f18f930937a97535","url":"https://api.github.com/repos/cuongct924/AI-