/repos/cuongct924/AI-delivery-portal-backend/commits/0f2a09e64802c28f618c43b7cfaf83b09d9c3c2f"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/111407982?v=4","events_url":"https://api.github.com/users/cuongct924/events{/privacy}","followers_url":"https://api.github.com/users/cuongct924/followers","following_url":"https://api.github.com/users/cuongct924/following{/other_user}","gists_url":"https://api.github.com/users/cuongct924/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/cuongct924","id":111407982,"login":"cuongct924","node_id":"U_kgDOBqPzbg","organizations_url":"https://api.github.com/users/cuongct924/orgs","received_events_url":"https://api.github.com/users/cuongct924/received_events","repos_url":"https://api.github.com/users/cuongct924/repos","site_admin":false,"starred_url":"https://api.github.com/users/cuongct924/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/cuongct924/subscriptions","type":"User","url":"https://api.github.com/users/cuongct924","user_view_type":"public"},"comments_url":"https://api.github.com/repos/cuongct924/AI-delivery-portal-backend/commits/85a997ca099c5927e93bc312262c30622128dfc3/comments","commit":{"author":{"date":"2026-09-17T05:51:34Z","email":"cuongct0902@gmail.com","name":"Cuongit1-hust"},"comment_count":0,"committer":{"date":"2026-09-17T05:51:34Z","email":"cuongct0902@gmail.com","name":"Cuongit1-hust"},"message":"chore: clean source code","tree":{"sha":"e2826c8d19abf16903895039071a889773900b66","url":"https://api.github.com/repos/cuongct924/AI-delivery-portal-backend/git/trees/e2826c8d19abf16903895039071a889773900b66"},"url":"https://api.github.com/repos/cuongct924/AI-delivery-portal-backend/git/commits/85a997ca099c5927e93bc312262c30622128dfc3","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/111407982?v=4","events_url":"https://api.github.com/use