INSERT INTO collection_pages VALUES('6234a5904884f344ebfc77251e224ae9d188422b8253cba6fc839ea936c69721','831a401396bbc664d1a7c36cbcd6093010b5d4b0cfc96526eb9193b53741105a','{"hasNext":false,"items":[{"author":{"account":null,"email":"anahita@example.com","name":"Anahita"},"authoredDate":"2026-08-04T21:08:59Z","committedDate":"2026-08-04T21:08:59Z","committer":{"account":null,"email":"anahita@example.com","name":"Anahita"},"observedAt":"2026-10-08T23:43:31.305Z","repositoryId":1298602654,"sha":"5ecfb222f6d84d3d7a64a80f4e699e5183c70810"}],"observedAt":"2026-10-08T23:43:31.305Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/anahita05/template-next.js/commits/5ecfb222f6d84d3d7a64a80f4e699e5183c70810/comments","commit":{"author":{"date":"2026-08-04T21:08:59Z","email":"anahita@example.com","name":"Anahita"},"comment_count":0,"committer":{"date":"2026-08-04T21:08:59Z","email":"anahita@example.com","name":"Anahita"},"message":"chore: upgrade dependencies, fix build errors, reorganize components\n\n- Bump Next.js 16.2.10 -> 16.3.0, React 19.2.7 -> 19.2.8, next-intl,\n  Zustand, lucide-react, @radix-ui/react-slot, tailwind-merge, and all\n  type packages to latest stable\n- Pin TypeScript to 6.0.3 and ESLint to 9.39.5 (latest versions still\n  supported by typescript-eslint; TS 7.0 and ESLint 10 currently break\n  typescript-eslint''s parser/scope-manager integration)\n- Override typescript-eslint sub-packages to 8.66.0 via pnpm-workspace\n  overrides to fix an ESLint 10-era scope manager incompatibility\n- Migrate eslint.config.mjs from FlatCompat legacy bridge to eslint-config-next''s\n  native flat config export\n- Fix tailwind.config.ts darkMode type error ([''class''] -> ''class'')\n- Fix malformed postcss.config.mjs plugin format (array -> object),\n  which was the root cause of the Turbopack/lightningcss build failure\n- Rename src/middleware.ts -> src/proxy.ts per the Next.js 16 proxy\n  convention (removes the middleware deprecation warning)\n- Add missing Nav.openMenu / Nav.closeMenu translation keys in\n  messages/en.json and messages/fa.json (fixed MISSING_MESSAGE build\n  error)\n- Fix react-hooks/set-state-in-effect lint error in ThemeSwitcher by\n  replacing the mount-effect + setState pattern with useSyncExternalStore\n- Normalize CRLF line endings in src/app/[locale]/layout.tsx\n- Reorganize src/components into layout/ (Navbar, Footer) and common/\n  (LocaleSwitcher, ThemeSwitcher, ThemeInitializer) subdirectories,\n  keeping ui/ for shadcn primitives, and update all import paths\n\nVerified: tsc --noEmit, eslint ., and next build all pass with zero\nerrors and zero warnings.","tree":{"sha":"d14c30da74ae604de442ff4b8736d9241375f2ca","url":"https://api.github.com/repos/anahita05/template-next.js/git/trees/d14c30da74ae604de442ff4b8736d9241375f2ca"},"url":"https://api.github.com/repos/anahita05/template-next.js/git/commits/5ecfb222f6d84d3d7a64a80f4e699e5183c70810","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/anahita05/template-next.js/commit/5ecfb222f6d84d3d7a64a80f4e699e5183c70810","node_id":"C_kwDOTWcantoAKDVlY2ZiMjIyZjZkODRkM2Q3YTY0YTgwZjRlNjk5ZTUxODNjNzA4MTA","parents":[],"sha":"5ecfb222f6d84d3d7a64a80f4e699e5183c70810","url":"https://api.github.com/repos/anahita05/template-next.js/commits/5ecfb222f6d84d3d7a64a80f4e699e5183c70810"}],"requestUrl":"https://api.github.com/repos/anahita05/template-next.js/commits?per_page=100&page=1&sha=5ecfb222f6d84d3d7a64a80f4e699e5183c70810&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T16%3A01%3A23.607Z"}');
